function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { collectSalesData, classifySalesDataByProduct, classifySalesDataByStore, filterValidProductData, collectWeatherData, collectEventData, collectSeasonalData, analyzeCorrelationSalesWeather, analyzeCorrelationSalesEvent, analyzeCorrelationSalesSeason, compareWithHistoricalData, findAlternativeComparisonData, validateComparisonPeriod } = window.aivicLogic;

  // 現在の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  let currentStoreId = '';
  let orderData = [];
  let selectedOrderIds = new Set();

  // 店舗マスタのテーブルインデックス（1番目）
  const storeTableIndex = 1;
  // 発注データのテーブルインデックス（7番目）
  const orderTableIndex = 7;
  // 商品マスタのテーブルインデックス（2番目）
  const productTableIndex = 2;
  // 需要予測結果のテーブルインデックス（6番目）
  const forecastTableIndex = 6;

  // エラー表示関数
  function showError(message) {
    window.aivicNotify.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify.success(message);
  }

  // ステータスクラス取得
  function getStatusClass(status) {
    switch (status) {
      case '送信済み': return 'status-sent';
      case '送信中': return 'status-sending';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  // 店舗選択肢を初期化
  async function initStoreOptions() {
    try {
      const stores = await window.aivicApi.list(storeTableIndex);
      const storeSelect = container.querySelector('#store-select');
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

      if (stores) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      showError('店舗データの取得に失敗しました');
    }
  }

  // 発注データ一覧を描画
  function renderOrderList(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="8" class="muted" style="text-align: center; padding: 2rem;">
            発注データがありません
          </td>
        </tr>
      `;
      updateSendButton();
      return;
    }

    tbody.innerHTML = orders.map(order => `
      <tr data-id="${order.発注ID}">
        <td>
          <input type="checkbox" class="order-checkbox" data-id="${order.発注ID}" 
                 ${selectedOrderIds.has(order.発注ID) ? 'checked' : ''}>
        </td>
        <td>${order.商品コード || ''}</td>
        <td>${order.商品名 || ''}</td>
        <td>${order.予測数量 || 0}</td>
        <td>${order.発注数量 || 0}</td>
        <td>${order.仕入先名 || ''}</td>
        <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
        <td>
          <span class="status-badge ${getStatusClass(order.発注ステータス)}">
            ${order.発注ステータス || '未送信'}
          </span>
        </td>
      </tr>
    `).join('');

    // チェックボックスのイベントリスナーを追加
    tbody.querySelectorAll('.order-checkbox').forEach(checkbox => {
      checkbox.addEventListener('change', handleOrderSelection);
    });

    updateSendButton();
  }

  // 発注選択処理
  function handleOrderSelection(event) {
    const orderId = event.target.dataset.id;
    if (event.target.checked) {
      selectedOrderIds.add(orderId);
    } else {
      selectedOrderIds.delete(orderId);
    }
    updateSendButton();
  }

  // 送信ボタンの状態更新
  function updateSendButton() {
    const sendButton = container.querySelector('#send-orders-btn');
    const hasSelection = selectedOrderIds.size > 0;
    const hasUnsent = orderData.some(order => 
      selectedOrderIds.has(order.発注ID) && order.発注ステータス !== '送信済み'
    );

    sendButton.disabled = !hasSelection || !hasUnsent;
  }

  // 発注データ検索
  async function searchOrders() {
    try {
      const storeId = container.querySelector('#store-select').value;
      const orderDate = container.querySelector('#order-date').value;

      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      if (!orderDate) {
        showError('発注日を入力してください');
        return;
      }

      currentStoreId = storeId;

      // 発注データを取得
      const orders = await window.aivicApi.list(orderTableIndex);
      const filteredOrders = orders.filter(order => 
        order.店舗ID === storeId && 
        order.発注日 === orderDate
      );

      // 商品マスタを取得して商品名を補完
      const products = await window.aivicApi.list(productTableIndex);
      const productMap = new Map(products.map(p => [p.商品ID, p]));

      // 発注データに商品情報を追加
      orderData = filteredOrders.map(order => ({
        ...order,
        商品名: productMap.get(order.商品ID)?.商品名 || '',
        商品コード: productMap.get(order.商品ID)?.商品コード || ''
      }));

      selectedOrderIds.clear();
      renderOrderList(orderData);

    } catch (error) {
      showError('発注データの検索に失敗しました');
    }
  }

  // 全選択/全解除
  function toggleAllSelection() {
    const selectAllCheckbox = container.querySelector('#select-all-checkbox');
    const orderCheckboxes = container.querySelectorAll('.order-checkbox');

    if (selectAllCheckbox.checked) {
      orderCheckboxes.forEach(checkbox => {
        checkbox.checked = true;
        selectedOrderIds.add(checkbox.dataset.id);
      });
    } else {
      orderCheckboxes.forEach(checkbox => {
        checkbox.checked = false;
        selectedOrderIds.delete(checkbox.dataset.id);
      });
    }

    updateSendButton();
  }

  // 発注送信処理
  async function sendOrders() {
    try {
      if (selectedOrderIds.size === 0) {
        showError('送信する発注を選択してください');
        return;
      }

      const sendButton = container.querySelector('#send-orders-btn');
      sendButton.disabled = true;
      sendButton.textContent = '送信中...';

      // 選択された発注データを取得
      const selectedOrders = orderData.filter(order => 
        selectedOrderIds.has(order.発注ID) && order.発注ステータス !== '送信済み'
      );

      if (selectedOrders.length === 0) {
        showError('送信可能な発注がありません');
        return;
      }

      // 業務ロジックを使用して発注データを検証・処理
      const salesData = await collectSalesData(currentStoreId, new Date().toISOString().split('T')[0]);
      const validProductData = filterValidProductData(selectedOrders);

      let successCount = 0;
      let errorCount = 0;

      // 各発注を順次送信
      for (const order of validProductData) {
        try {
          // ステータスを送信中に更新
          await window.aivicApi.update(orderTableIndex, order.発注ID, {
            ...order,
            発注ステータス: '送信中',
            送信日時: new Date().toISOString()
          });

          // 実際の送信処理をシミュレート（実際のAPIエンドポイントに送信）
          const sendResult = await simulateOrderSend(order);

          if (sendResult.success) {
            // 送信成功時のステータス更新
            await window.aivicApi.update(orderTableIndex, order.発注ID, {
              ...order,
              発注ステータス: '送信済み',
              送信完了日時: new Date().toISOString(),
              送信結果: sendResult.message
            });
            successCount++;
          } else {
            // 送信失敗時のステータス更新
            await window.aivicApi.update(orderTableIndex, order.発注ID, {
              ...order,
              発注ステータス: 'エラー',
              エラーメッセージ: sendResult.error
            });
            errorCount++;
          }
        } catch (error) {
          // エラー時のステータス更新
          await window.aivicApi.update(orderTableIndex, order.発注ID, {
            ...order,
            発注ステータス: 'エラー',
            エラーメッセージ: error.message
          });
          errorCount++;
        }
      }

      // 結果表示
      if (successCount > 0) {
        showSuccess(`${successCount}件の発注を送信しました`);
      }
      if (errorCount > 0) {
        showError(`${errorCount}件の発注でエラーが発生しました`);
      }

      // 発注一覧を再読み込み
      await searchOrders();

    } catch (error) {
      showError('発注送信処理でエラーが発生しました: ' + error.message);
    } finally {
      const sendButton = container.querySelector('#send-orders-btn');
      sendButton.disabled = false;
      sendButton.textContent = '選択した発注を送信';
    }
  }

  // 発注送信のシミュレーション（実際の実装では外部APIを呼び出し）
  async function simulateOrderSend(order) {
    // 実際の実装では、仕入先のAPIエンドポイントに発注データを送信
    return new Promise((resolve) => {
      setTimeout(() => {
        // 90%の確率で成功とする
        const success = Math.random() > 0.1;
        if (success) {
          resolve({
            success: true,
            message: '発注が正常に送信されました',
            orderId: order.発注ID
          });
        } else {
          resolve({
            success: false,
            error: 'ネットワークエラーが発生しました'
          });
        }
      }, 1000);
    });
  }

  // 発注履歴表示
  async function showOrderHistory() {
    try {
      const storeId = container.querySelector('#store-select').value;

      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      // 過去30日間の発注履歴を取得
      const orders = await window.aivicApi.list(orderTableIndex);
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const historyOrders = orders.filter(order => 
        order.店舗ID === storeId && 
        new Date(order.発注日) >= thirtyDaysAgo &&
        order.発注ステータス === '送信済み'
      );

      // 商品マスタを取得
      const products = await window.aivicApi.list(productTableIndex);
      const productMap = new Map(products.map(p => [p.商品ID, p]));

      // 履歴データに商品情報を追加
      const enrichedHistory = historyOrders.map(order => ({
        ...order,
        商品名: productMap.get(order.商品ID)?.商品名 || '',
        商品コード: productMap.get(order.商品ID)?.商品コード || ''
      }));

      // 履歴表示（簡易的にアラートで表示、実際の実装では専用画面に遷移）
      if (enrichedHistory.length === 0) {
        showError('発注履歴がありません');
      } else {
        showSuccess(`過去30日間の発注履歴: ${enrichedHistory.length}件`);
        // 実際の実装では履歴画面に遷移
        console.log('発注履歴:', enrichedHistory);
      }

    } catch (error) {
      showError('発注履歴の取得に失敗しました');
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 検索ボタン
    const searchButton = container.querySelector('#search-orders-btn');
    if (searchButton) {
      searchButton.addEventListener('click', searchOrders);
    }

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all-checkbox');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', toggleAllSelection);
    }

    // 送信ボタン
    const sendButton = container.querySelector('#send-orders-btn');
    if (sendButton) {
      sendButton.addEventListener('click', sendOrders);
    }

    // 履歴表示ボタン
    const historyButton = container.querySelector('#show-history-btn');
    if (historyButton) {
      historyButton.addEventListener('click', showOrderHistory);
    }

    // 店舗選択の変更
    const storeSelect = container.querySelector('#store-select');
    if (storeSelect) {
      storeSelect.addEventListener('change', () => {
        selectedOrderIds.clear();
        orderData = [];
        renderOrderList([]);
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await initStoreOptions();
      setupEventListeners();
      renderOrderList([]);
    } catch (error) {
      showError('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
